{
  "bbb_prediction": "fail",
  "claims": [
    {
      "card_ids": ["C11"],
      "claim": "Mithramycin, a large polyglycosylated natural product, achieved only a 0.12 CSF:plasma ratio in monkeys with little brain distribution, directly demonstrating poor CNS access for this glycoside-rich scaffold class.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C05"],
      "claim": "Digitoxin showed a very low CSF/plasma ratio of 0.01-0.03 in dogs, providing direct evidence that bulky glycosides do not readily penetrate the blood-brain barrier.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C03"],
      "claim": "SC-4453, a cardiac glycoside, had the lowest brain concentration among tissues at steady state in guinea pigs, indicating BBB impermeability for this structural family.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C06"],
      "claim": "Orientin, a polar glycoside, showed low brain levels after intravenous administration in rats due to difficulty crossing the BBB, supporting poor CNS penetration for highly polar glycosylated compounds.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C08"],
      "claim": "Erythromycin, a large macrocyclic glycoside-like antibiotic, achieved only 0.1-2.5 µg/mL CSF versus 8-12 µg/mL serum even in meningitis, showing that large polar natural products have inadequate CNS access.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C10"],
      "claim": "Gentamicin, an aminoglycoside bearing multiple amino and hydroxyl groups, showed no meaningful CSF migration after systemic administration, consistent with the amino-sugar and polyhydroxylated features of the query.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C04"],
      "claim": "Loganin, an iridoid glycoside, had the lowest brain levels after systemic administration in rats, reinforcing that glycosylated natural products generally cross the BBB poorly.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C01"],
      "claim": "Epimedin B, a glycosylated flavonol, was the least concentrated compound in rat brain in a tissue distribution study, demonstrating poor BBB penetration for large glycosylated polyphenols.",
      "evidence_role": "supportive"
    }
  ],
  "confidence": "high",
  "decision_summary": "The query is a large, highly polar anthracycline-type glycoside with an amino sugar and multiple hydroxyl groups. Direct and transferable evidence from glycoside and aminoglycoside analogs consistently shows poor CSF/brain penetration after systemic administration, so the query is predicted to lack meaningful CNS access.",
  "evidence_gaps": [
    "No direct CSF or brain pharmacokinetic measurement for the exact query molecule.",
    "No explicit P-glycoprotein or efflux-transporter inhibition data for the query.",
    "Extrapolation relies on structurally related glycosylated natural products rather than the identical anthracycline scaffold."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

